        print(f'You are at {self.player.current_location}')

    def move(self, direction):
        if direction == 'north' and self.player.current_location == 'beach':
            self.player.current_location = 'forest'
        elif direction =='south' and self.player.current_location == 'forest':
            self.player.current_location = 'beach'

